\[
\begin{aligned}
&|K|^2 V^2 = \omega^2 \\
&\implies |K|^2/c^2 = n^2 \omega^2/\omega^2\\
&=  n^2 = \sum_{\alpha} \varepsilon_\alpha^{-1}\\
&=\\
\end{align*}

